ALTER TABLE "City" ADD COLUMN "state" INTEGER, ADD COLUMN "stateTerm" INTEGER, ADD COLUMN "parentCityKey" INTEGER;
ALTER TABLE "General" ADD COLUMN "movePath" INTEGER[] NOT NULL DEFAULT ARRAY[]::INTEGER[];
ALTER TABLE "City" ADD CONSTRAINT "City_state_range" CHECK (("state" IS NULL AND "stateTerm" IS NULL) OR ("state" IS NOT NULL AND "stateTerm" IS NOT NULL AND "state" BETWEEN 0 AND 49 AND "stateTerm" BETWEEN 0 AND 2147483647));
